window.addEventListener("load",function(){try{let o=sessionStorage.getItem("theme");if(JSON.parse(o).settings.layout.darkMode){var e="dark";Apex.tooltip={theme:e};var a={chart:{type:"pie",width:270,height:430},colors:LTDdata.LTDcolors,dataLabels:{enabled:!1},legend:{position:"bottom",horizontalAlign:"center",fontSize:"14px",markers:{width:10,height:10,offsetX:-5,offsetY:0},itemMargin:{horizontal:10,vertical:10}},stroke:{colors:["#0e1726"]},series:LTDdata.LTDchartvalue,labels:LTDdata.LTDlabel}}else{var e="dark";Apex.tooltip={theme:e};var a={chart:{type:"pie",width:270,height:430},colors:LTDdata.LTDcolors,dataLabels:{enabled:!1},legend:{position:"bottom",horizontalAlign:"center",fontSize:"14px",markers:{width:10,height:10,offsetX:-5,offsetY:0},itemMargin:{horizontal:10,vertical:10}},stroke:{colors:["#fff"]},series:LTDdata.LTDchartvalue,labels:LTDdata.LTDlabel}}var t=new ApexCharts(document.querySelector("#leave-type-distribution"),a);t.render(),document.querySelector(".theme-toggle").addEventListener("click",function(){let r=sessionStorage.getItem("theme");JSON.parse(r).settings.layout.darkMode?t.updateOptions({stroke:{colors:["#0e1726"]},plotOptions:{pie:{donut:{labels:{value:{color:"#bfc9d4"}}}}}}):t.updateOptions({stroke:{colors:["#fff"]},plotOptions:{pie:{donut:{labels:{value:{color:"#0e1726"}}}}}})})}catch(o){console.log(o)}});
